/bin/zsh -lc "python3 -c 'import json,copy; x=json.load(open(\"input.json\")); y=copy.deepcopy(x); fixes={\"g02\":(\"m6\",\"Orvane Ledger\",\" We also read about Orvane Ledger sponsoring a park cleanup.\"),\"g06\":(\"m3\",\"Pellwick Harbor\",\" We also read about Pellwick Harbor sponsoring a beach cleanup.\"),\"g07\":(\"m4\",\"Arvenholt Systems\",\" We also read about Arvenholt Systems sponsoring a public chess table.\"),\"g10\":(\"m2\",\"Solvren Taller\",\" También leí una noticia sobre Solvren Taller y su nuevo mural.\"),\"g12\":(\"m4\",\"Pelmora Water\",\" We also read about Pelmora Water sponsoring a river cleanup.\")}; changed=[]
for s,t in zip(x[\"stories\"],y[\"stories\"]):
 if s[\"id\"] in fixes:
  mid,org,sentence=fixes[s[\"id\"]]; m=next(m for m in t[\"memories\"] if m[\"id\"]==mid); m[\"text\"]+=sentence; m[\"organizations\"].append({\"surface\":org,\"org\":org,\"relation\":\"other\"})
 for a,b in zip(s[\"memories\"],t[\"memories\"]):
  if a"'!=b:
   assert (s["id"],a["id"])==(s["id"],fixes[s["id"]][0]); assert all(a[k]==b[k] for k in a if k not in ["text","organizations"]); changed.append(s["id"]+" "+a["id"])
  assert all(z["surface"] in b["text"] for z in b["organizations"]+b["names"])
  if b["filler"]:
   assert not b["jobs"]; assert any(z["org"] in {u["org"] for u in t["timeline"]} for z in b["organizations"])
 assert all(s[k]==t[k] for k in s if k!="memories")
assert len(changed)==5
print("Validated: only text and organization annotations changed in " + ", ".join(changed) + "; all fillers name a timeline organization and retain empty jobs.")'"'"

